mapper.select:
WITH BASE_TBL AS ( SELECT ROW_NUMBER() OVER (PARTITION BY A.RECIPI_MNG_NO ORDER BY A.PENSN_GIVE_STTS_OCRN_YMD DESC, A.TASKWK_OCRN_SQNCE DESC) AS RNO , A.* , B.TRPR_INFO_NO FROM AEB131 A , AEB130 B WHERE A.DEL_YN = 'N' AND A.RECIPI_MNG_NO = B.RECIPI_MNG_NO ) , LAST_TBL AS ( SELECT RECIPI_MNG_NO , CASE WHEN PENSN_GIVE_STTS_SE_CD IN ('03','05','06') THEN 'N' ELSE 'Y' END AS NOW_PENSN_GIVE_YN FROM BASE_TBL WHERE RNO = 1 ) , FIRST_TBL AS ( SELECT * FROM ( SELECT ROW_NUMBER() OVER (PARTITION BY A.RECIPI_MNG_NO ORDER BY RNO DESC) AS RRNO , A.* FROM BASE_TBL A WHERE A.PENSN_GIVE_STTS_SE_CD = '01' ) WHERE RRNO = 1 ) , MATCH_TBL AS ( SELECT A.NOW_PENSN_GIVE_YN , B.* FROM LAST_TBL A , FIRST_TBL B WHERE A.RECIPI_MNG_NO = B.RECIPI_MNG_NO )
, INST_TBL AS ( SELECT INST_NO FROM SAA000 WHERE UNT_TASKWK_SE_CD IN ('U01','U04') START WITH INST_NO IN ( SELECT INST_NO FROM SAB230 WHERE USER_ID = #{USER_ID2} UNION SELECT INST_NO FROM SAA000 WHERE 1=1 AND UNT_TASKWK_SE_CD = 'U04' AND RGN_CD IN ( SELECT B.RGN_CD FROM SAB230 A , SAA000 B WHERE A.USER_ID = #{USER_ID2} AND A.INST_NO = B.INST_NO AND B.UNT_TASKWK_SE_CD = 'U05' ) ) CONNECT BY UP_INST_NO = PRIOR INST_NO ) , AUTHDATA_TBL AS ( SELECT DISTINCT A.TRPR_INFO_NO , B.PIC_INST_NO , C.LASTA_LVNG_SHELTR_NO , C.MTCHNG_PIC_INST_NO FROM SEB100 A , SEB150 B , AEB132 C WHERE A.CASE_MNG_NO = B.CASE_MNG_NO AND A.CASE_MNG_ODRNO = B.CASE_MNG_ODRNO AND A.UNT_TASKWK_SE_CD = 'U04' AND A.TRPR_INFO_NO = C.TRPR_INFO_NO ) , AUTH_TBL AS ( SELECT TRPR_INFO_NO FROM AUTHDATA_TBL WHERE 1 = 1 AND PIC_INST_NO IN ( SELECT INST_NO FROM INST_TBL ) UNION SELECT TRPR_INFO_NO FROM AUTHDATA_TBL WHERE 1 = 1 AND LASTA_LVNG_SHELTR_NO IN ( SELECT INST_NO FROM INST_TBL ) UNION SELECT TRPR_INFO_NO FROM AUTHDATA_TBL WHERE 1 = 1 AND MTCHNG_PIC_INST_NO IN ( SELECT INST_NO FROM INST_TBL ) )
SELECT Z.* FROM ( SELECT * FROM ( /* selectSplymtEnblrMtchngList - BaekGyuHa */ SELECT ROWNUM AS SEQ , ENBLR_MNG_NO , RRNO_ENCPT , RRNO , BRTH_YMD , SXDC_SE_CD , TRPR_NM_ENCPT , TRPR_NM , TRPR_INFO_NO , INDV_IDNTFC_NO , LASTA_LVNG_SHELTR_NO , LASTA_LVNG_SHELTR_NM , LASTA_LVNG_YMD , ISRY_PAST_YEARS3_ENTRNC_PRD_SUM_DAYCNT , ISRY_RECENT_YEAR1_CTNUTN_ENTRNC_YN , ISRY_RECENT_YEAR1_CTNUTN_ENTRNC_YN_NM , UNITY_PAST_YEARS3_ENTRNC_PRD_SUM_DAYCNT , UNITY_RECENT_YEAR1_CTNUTN_ENTRNC_YN , UNITY_RECENT_YEAR1_CTNUTN_ENTRNC_YN_NM , RECIPI_MNG_NO , RECIPI_MTCHNG_YN , RECIPI_MTCHNG_YN_NM , MTCHNG_PIC_ENFSN_NO , MTCHNG_PIC_ENFSN_NM , MTCHNG_PIC_ENFSN_NM_ENCPT , MTCHNG_PIC_INST_NO , MTCHNG_PIC_INST_NM , MTCHNG_PIC_TELNO , MTCHNG_YMD , TRPR_BRTH_YMD , PENSN_GIVE_STTS_SE_CD , RCMDTN_SHELTR_NO , RCMDTN_YMD , RCMDTN_SHELTR_NM , NOW_PENSN_GIVE_YN , NOW_PENSN_GIVE_YN_NM , PENSN_GIVE_STTS_OCRN_YMD , PENSN_GIVE_STTS_BGNG_YM , MM_PENSN_GIVE_AMT , PENSN_GIVE_CHG_LCGOV_NO , PENSN_GIVE_CHG_LCGOV_NM , TASKWK_OCRN_SQNCE , MBL_TELNO_ENCPT , MBL_TELNO , TRPR_TELNO , EML_ADDR_ENCPT , EML_ADDR , SNS_SE_CD , MSNGR_ID_ENCPT , MSNGR_ID , ADDR FROM ( SELECT A.ENBLR_MNG_NO , D.RRNO_ENCPT , REPLACE(C##RG.DEC_B64(D.RRNO_ENCPT), '-', '') AS RRNO , D.BRTH_YMD , D.SXDC_SE_CD , C.TRPR_NM_ENCPT , C##RG.DEC_B64(C.TRPR_NM_ENCPT) AS TRPR_NM , A.TRPR_INFO_NO , C.INDV_IDNTFC_NO , A.LASTA_LVNG_SHELTR_NO , A.LASTA_LVNG_SHELTR_NM , REPLACE(A.LASTA_LVNG_YMD, '-', '') AS LASTA_LVNG_YMD , A.ISRY_PAST_YEARS3_ENTRNC_PRD_SUM_DAYCNT , A.ISRY_RECENT_YEAR1_CTNUTN_ENTRNC_YN , CASE WHEN A.ISRY_RECENT_YEAR1_CTNUTN_ENTRNC_YN = 'Y' THEN '예' ELSE '아니오' END ISRY_RECENT_YEAR1_CTNUTN_ENTRNC_YN_NM , A.UNITY_PAST_YEARS3_ENTRNC_PRD_SUM_DAYCNT , A.UNITY_RECENT_YEAR1_CTNUTN_ENTRNC_YN , CASE WHEN A.UNITY_RECENT_YEAR1_CTNUTN_ENTRNC_YN = 'Y' THEN '예' ELSE '아니오' END UNITY_RECENT_YEAR1_CTNUTN_ENTRNC_YN_NM , A.RECIPI_MNG_NO , CASE WHEN A.RECIPI_MNG_NO IS NOT NULL THEN 'Y' ELSE 'N' END RECIPI_MTCHNG_YN , CASE WHEN A.RECIPI_MNG_NO IS NOT NULL THEN '예' ELSE '아니오' END RECIPI_MTCHNG_YN_NM , A.MTCHNG_PIC_ENFSN_NO , (SELECT C##RG.DEC_B64(F.FLNM_ENCPT) FROM SCA100 F /* 종사자 */ WHERE F.ENFSN_NO = A.MTCHNG_PIC_ENFSN_NO) AS MTCHNG_PIC_ENFSN_NM , (SELECT F.FLNM_ENCPT FROM SCA100 F /* 종사자 */ WHERE F.ENFSN_NO = A.MTCHNG_PIC_ENFSN_NO) AS MTCHNG_PIC_ENFSN_NM_ENCPT , A.MTCHNG_PIC_INST_NO , (SELECT INST_NM FROM SAA000 F /* 기관 */ WHERE F.INST_NO = A.MTCHNG_PIC_INST_NO) AS MTCHNG_PIC_INST_NM , REPLACE(A.MTCHNG_PIC_TELNO, '-', '') AS MTCHNG_PIC_TELNO , A.MTCHNG_YMD , C.TRPR_BRTH_YMD , B.PENSN_GIVE_STTS_SE_CD , B.RCMDTN_SHELTR_NO , REPLACE(B.RCMDTN_YMD, '-', '') AS RCMDTN_YMD , (SELECT INST_NM FROM SAA000 F /* 기관 */ WHERE F.INST_NO = B.RCMDTN_SHELTR_NO) AS RCMDTN_SHELTR_NM , B.NOW_PENSN_GIVE_YN , CASE WHEN B.NOW_PENSN_GIVE_YN IS NULL THEN '' WHEN (B.PENSN_GIVE_STTS_SE_CD = '03' OR B.PENSN_GIVE_STTS_SE_CD = '05' OR B.PENSN_GIVE_STTS_SE_CD = '06') THEN '아니오' ELSE '예' END NOW_PENSN_GIVE_YN_NM , B.PENSN_GIVE_STTS_OCRN_YMD , B.PENSN_GIVE_STTS_BGNG_YM , B.MM_PENSN_GIVE_AMT , B.PENSN_GIVE_CHG_LCGOV_NO , (SELECT INST_NM FROM SAA000 F /* 기관 */ WHERE F.INST_NO = B.PENSN_GIVE_CHG_LCGOV_NO) AS PENSN_GIVE_CHG_LCGOV_NM , B.TASKWK_OCRN_SQNCE , C.MBL_TELNO_ENCPT , REPLACE(C##RG.DEC_B64(C.MBL_TELNO_ENCPT), '-', '') AS MBL_TELNO , REPLACE(C##RG.DEC_B64(C.TRPR_TELNO), '-', '') AS TRPR_TELNO , C.EML_ADDR_ENCPT , C##RG.DEC_B64(C.EML_ADDR_ENCPT) AS EML_ADDR , C.SNS_SE_CD , C.MSNGR_ID_ENCPT , C##RG.DEC_B64(C.MSNGR_ID_ENCPT) AS MSNGR_ID , CASE WHEN C.PST_ADDR IS NOT NULL AND C.DADDR IS NOT NULL THEN C.PST_ADDR || ' ' || C.DADDR WHEN C.PST_ADDR IS NOT NULL AND C.DADDR IS NULL THEN C.PST_ADDR ELSE '' END ADDR FROM AEB132 A /* 자립지원수당수급가능자 */ , MATCH_TBL B /* 자립지원수당상태 */ , SEA200 C /* 대상자정보 */ , SCA300 D /* 개인정보 */
, AUTH_TBL E
WHERE A.RECIPI_MNG_NO = B.RECIPI_MNG_NO(+) AND A.TRPR_INFO_NO = C.TRPR_INFO_NO AND C.INDV_IDNTFC_NO = D.INDV_IDNTFC_NO(+) AND NOT EXISTS ( SELECT 1 FROM AEB130 WHERE TRPR_INFO_NO = A.TRPR_INFO_NO )
AND A.TRPR_INFO_NO = E.TRPR_INFO_NO
) WHERE 1=1
) ) Z WHERE SEQ >= #{START_IDX} AND SEQ <= #{LAST_IDX}
